use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert a count of days since the Unix epoch (1970-01-01) into a
/// (year, month, day) triple, using Howard Hinnant's civil-from-days
/// algorithm. Valid across the whole proleptic Gregorian range.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as i64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let year = if m <= 2 { y + 1 } else { y };
    (year, m, d)
}

/// Format the instant `seconds` (Unix time) as a fixed-width `YYYY-MM-DD`
/// string. The year is clamped to four digits so the result is always
/// exactly 10 characters, satisfying `len(date) == 10`.
fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (year, month, day) = civil_from_days(days);
    let year = year.rem_euclid(10_000); // keep to 4 digits, always >= 0
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The one authority this node holds: read the wall clock.
        let now = wall_clock::now();
        let started = now.seconds; // u64, so `started >= 0` holds by type.
        let date = format_date(started); // exactly 10 chars.

        RunInfo { date, started }
    }
}

export!(Node);
